use soroban_sdk::{contract, contractimpl, contracttype, Address, Env};

#[contracttype]
pub enum DataKey {
    Balance(Address),
    Allowance(Address, Address),
}

#[contract]
pub struct Token;

#[contractimpl]
impl Token {
    // A balance in temporary storage: it is reclaimed rather than archived, so the
    // holder's funds disappear with no trace and no way to restore them.
    pub fn receive(env: Env, to: Address, amount: i128) {
        to.require_auth();
        env.storage()
            .temporary()
            .set(&DataKey::Balance(to.clone()), &amount);
    }

    // Per-account data in the one entry every call loads.
    pub fn set_allowance(env: Env, user: Address, spender: Address, amount: i128) {
        user.require_auth();
        env.storage().instance().set(
            &DataKey::Allowance(user.clone(), spender.clone()),
            &amount,
        );
    }
}

