use soroban_sdk::{contract, contractimpl, contracttype, Address, Env};

#[contracttype]
pub enum DataKey {
    Balance(Address),
    FeeBps,
    Nonce(Address),
}

#[contract]
pub struct Token;

#[contractimpl]
impl Token {
    // A balance belongs in persistent storage: it expires, but it is restorable.
    pub fn receive(env: Env, to: Address, amount: i128) {
        to.require_auth();
        env.storage()
            .persistent()
            .set(&DataKey::Balance(to.clone()), &amount);
    }

    // Contract-wide configuration is what instance storage is for.
    pub fn set_fee(env: Env, admin: Address, bps: u32) {
        admin.require_auth();
        env.storage().instance().set(&DataKey::FeeBps, &bps);
    }

    // A nonce is worthless once it has expired, so temporary storage is correct here.
    pub fn begin(env: Env, who: Address) {
        env.storage().temporary().set(&DataKey::Nonce(who.clone()), &1u32);
    }
}
